const app = document.getElementById('app');
const state = { csrf: null, user: null, draft: {}, startedAt: Date.now(), confirmation: null };

const escapeHtml = (value) => String(value ?? '').replace(/[&<>'"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[c]));
const fmtDate = (value) => value ? new Intl.DateTimeFormat('en-US', { dateStyle: 'medium' }).format(new Date(value)) : 'Not provided';
const fmtTime = (value) => value ? new Intl.DateTimeFormat('en-US', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : 'Not provided';
const statusClass = (status) => `status-${String(status || '').toLowerCase().replaceAll(' ', '-')}`;
const statusBadge = (status) => `<span class="status ${statusClass(status)}">${escapeHtml(status)}</span>`;
const vehicleName = (item) => [item.color, item.make || item.vehicle_make, item.model || item.vehicle_model, item.type || item.vehicle_type].filter(Boolean).join(' ') || 'Vehicle details not provided';

function publicHeader(active = '') {
  return `<header class="site-header"><nav class="public-nav" aria-label="Primary navigation">
    <a class="brand" href="/" data-route><span class="brand-mark">VW</span><span><small>County public service</small>VehicleWatch</span></a>
    <button class="menu-toggle" type="button" aria-label="Toggle navigation" aria-expanded="false">Menu</button>
    <div class="nav-links">
      <a href="/" data-route class="${active === 'home' ? 'active' : ''}">Home</a>
      <a href="/report" data-route class="${active === 'report' ? 'active' : ''}">Report vehicle</a>
      <a href="/status" data-route class="${active === 'status' ? 'active' : ''}">Check status</a>
      <a href="/about" data-route class="${active === 'about' ? 'active' : ''}">About</a>
      <a href="/report" data-route class="nav-action">Report an abandoned vehicle</a>
    </div>
  </nav></header>`;
}
function footer() {
  return `<footer class="footer"><div class="footer-inner"><div><strong>VehicleWatch</strong><p>Community reporting for a safer, cleaner county.</p></div><div><a href="/county" data-route>County information</a> &nbsp; <a href="/contact" data-route>Contact</a> &nbsp; <a href="/faq" data-route>FAQ</a> &nbsp; <a href="/staff/login" data-route>Staff sign in</a></div></div></footer>`;
}
function publicPage(active, content) { app.innerHTML = `${publicHeader(active)}<main class="page">${content}</main>${footer()}`; bindCommon(); }
function bindCommon() {
  document.querySelectorAll('[data-route]').forEach(a => a.addEventListener('click', event => { if (event.metaKey || event.ctrlKey) return; event.preventDefault(); navigate(a.getAttribute('href')); }));
  const toggle = document.querySelector('.menu-toggle');
  if (toggle) toggle.addEventListener('click', () => { const nav = document.querySelector('.nav-links'); const next = !nav.classList.contains('open'); nav.classList.toggle('open', next); toggle.setAttribute('aria-expanded', String(next)); });
}
function navigate(path, replace = false) { history[replace ? 'replaceState' : 'pushState']({}, '', path); render(); window.scrollTo({ top: 0, behavior: 'instant' }); }
window.addEventListener('popstate', render);

async function api(url, options = {}) {
  const headers = { ...(options.body ? { 'Content-Type': 'application/json' } : {}), ...(options.headers || {}) };
  if (state.csrf && !['GET', 'HEAD'].includes((options.method || 'GET').toUpperCase())) headers['X-CSRF-Token'] = state.csrf;
  const response = await fetch(url, { ...options, headers, credentials: 'same-origin' });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.error || 'Something went wrong.');
  return data;
}
function friendlyError(error) { return `<div class="notice warning" role="alert">${escapeHtml(error.message || 'Something went wrong. Please try again.')}</div>`; }
function toast(message) { const el = document.createElement('div'); el.className = 'notice success'; el.style.cssText = 'position:fixed;right:16px;bottom:18px;z-index:99;box-shadow:var(--shadow)'; el.textContent = message; document.body.append(el); setTimeout(() => el.remove(), 3500); }

function home() {
  publicPage('home', `<section class="hero"><div><div class="eyebrow">A county public-service tool</div><h1>Report an abandoned vehicle.</h1><p class="lead">Take a clear photo, tell us where the vehicle is, and submit a report in about a minute. County staff review every report.</p><div class="row"><a class="btn" href="/report" data-route>Report an abandoned vehicle <span aria-hidden="true">→</span></a><a class="btn outline" href="/status" data-route>Check a report status</a></div></div><aside class="hero-card"><h2>Before you begin</h2><div class="stack"><div><strong>1. Take a photo</strong><br><span class="subtle">Include the vehicle and, if possible, the license plate.</span></div><div><strong>2. Share the location</strong><br><span class="subtle">Use your location or enter the nearest address.</span></div><div><strong>3. Keep your Report ID</strong><br><span class="subtle">Use it to check progress without an account.</span></div></div></aside></section>
  <section class="feature-grid" aria-label="How reporting works"><article class="feature"><div class="feature-icon">01</div><h3>Simple to submit</h3><p class="subtle">No public account or lengthy form. Share only details that help staff identify the vehicle.</p></article><article class="feature"><div class="feature-icon">02</div><h3>Reviewed by people</h3><p class="subtle">Automated checks can flag similar reports, but authorized staff make the decisions.</p></article><article class="feature"><div class="feature-icon">03</div><h3>Follow the report</h3><p class="subtle">Your Report ID lets you see the public review status at any time.</p></article></section>
  <section class="content-grid section"><article class="card prose"><h2>What happens after you report?</h2><p>Staff assess the vehicle information, location, and any related reports. A report does not guarantee immediate removal. It helps the county investigate and decide the appropriate next step.</p><a href="/about" data-route>Learn how the program works →</a></article><aside class="card"><h3>Emergency or immediate danger?</h3><p class="subtle">Do not use this form for emergencies, traffic hazards, or crimes in progress. Call emergency services instead.</p><a href="/contact" data-route>Find contact information</a></aside></section>`);
}
function infoPage(kind) {
  const pages = {
    about: ['About the program', `<p>VehicleWatch is a modular reporting tool designed for a county abandoned-vehicle program. It is not an official agency website unless adopted and branded by an authorized county department.</p><h2>How reporting works</h2><ol><li>A resident submits a photo, location, and useful vehicle details.</li><li>Staff review the report and check for related reports or an existing vehicle case.</li><li>Staff may verify, request more information internally, link related reports, or close an invalid report.</li><li>When appropriate, a vehicle case is managed through resolution and archived.</li></ol><p>Reports are reviewed individually. Submitting a report does not guarantee towing or immediate action.</p>`],
    faq: ['Frequently asked questions', `<div class="faq"><details open><summary>Do I need an account to submit a report?</summary><p>No. You can submit a report without creating an account. Keep your Report ID to check its public status.</p></details><details><summary>What should I include in the photo?</summary><p>Take a clear photo of the vehicle. If it is safe and visible, include the license plate and the surrounding location.</p></details><details><summary>Can I report the same vehicle more than once?</summary><p>You may submit a new observation when it is helpful, but the system may flag similar reports for staff review. Staff decide whether reports concern the same vehicle.</p></details><details><summary>Why is a report not immediately resolved?</summary><p>County staff may need to verify ownership, location, safety conditions, and applicable procedures before taking action.</p></details><details><summary>Can I see staff notes or precise map locations?</summary><p>No. Public status is intentionally limited to protect operational and sensitive information.</p></details></div>`],
    county: ['County information', `<p>This deployment uses a neutral, replaceable county identity. An authorized county or department can add its logo, service-area information, policies, and official contact details without changing the reporting workflow.</p><div class="notice"><strong>For implementers:</strong> Replace this page with the adopted agency’s jurisdiction, public records notice, privacy policy, and local abandoned-vehicle ordinance resources.</div><h2>Service area</h2><p>Reports should concern vehicles within the participating county’s jurisdiction. Reports outside the service area may be closed or referred to the appropriate agency.</p>`],
    contact: ['Contact information', `<p>For questions about this reporting program, contact the participating county department using its officially published contact channels.</p><div class="card tight"><h3>Immediate danger or emergency</h3><p>Call emergency services. Do not submit this form for an urgent safety issue, traffic obstruction, or crime in progress.</p></div><h2>Questions about an existing report</h2><p>Use <a href="/status" data-route>Check status</a> with your Report ID first. That page provides the public information available for a submitted report.</p>`]
  };
  const [title, content] = pages[kind];
  publicPage(kind === 'about' ? 'about' : '', `<div class="page-title"><div class="breadcrumbs"><a href="/" data-route>Home</a> / ${escapeHtml(title)}</div><h1>${escapeHtml(title)}</h1></div><article class="prose">${content}</article>`);
}

function reportPage(step = 1) {
  const d = state.draft;
  const steps = ['Photo', 'Vehicle', 'Location', 'Review'];
  const progress = `<div class="progress">${steps.map((name, i) => `<div class="step ${i + 1 < step ? 'done' : i + 1 === step ? 'current' : ''}" data-n="${i + 1}">${name}</div>`).join('')}</div>`;
  let content = '';
  if (step === 1) content = `<h1>Add a vehicle photo</h1><p class="lead">A clear photo helps staff identify the vehicle. We remove image metadata before storing the report.</p><div id="photo-error"></div><label class="upload-zone" for="photo-input">${d.photoData ? `<img class="upload-preview" src="${d.photoData}" alt="Selected vehicle photo" />` : `<span><strong>Take or upload a photo</strong><br><span class="hint">JPG, PNG, or WebP · 5 MB maximum after processing</span></span>`}<input id="photo-input" type="file" accept="image/jpeg,image/png,image/webp" capture="environment"></label><div class="row" style="margin-top:18px">${d.photoData ? '<button class="btn secondary" id="remove-photo" type="button">Remove photo</button>' : ''}<button class="btn" id="photo-next" type="button">Continue</button></div>`;
  if (step === 2) content = `<h1>Vehicle information</h1><p class="lead">Add what you can see. Only the details marked required are needed.</p><form id="vehicle-form" novalidate><div class="form-grid"><div class="field"><label for="plate">License plate <span class="hint">optional</span></label><input id="plate" maxlength="16" value="${escapeHtml(d.plate || '')}" placeholder="ABC 123"></div><div class="field"><label for="plateState">Plate state <span class="hint">optional</span></label><input id="plateState" maxlength="24" value="${escapeHtml(d.plateState || '')}" placeholder="HI"></div><div class="field"><label for="make">Make <span class="hint">optional</span></label><input id="make" maxlength="60" value="${escapeHtml(d.make || '')}" placeholder="Toyota"></div><div class="field"><label for="model">Model <span class="hint">optional</span></label><input id="model" maxlength="60" value="${escapeHtml(d.model || '')}" placeholder="Camry"></div><div class="field"><label for="color">Color <span class="hint">optional</span></label><input id="color" maxlength="40" value="${escapeHtml(d.color || '')}" placeholder="Silver"></div><div class="field"><label for="vehicleType">Vehicle type <span class="hint">optional</span></label><select id="vehicleType"><option value="">Select type</option>${['Car / Sedan','Truck','SUV','Van','Motorcycle','Trailer','Other'].map(v => `<option ${d.vehicleType === v ? 'selected' : ''}>${v}</option>`).join('')}</select></div><div class="field full"><label for="description">What did you observe? <span class="required">required if no vehicle details</span></label><textarea id="description" maxlength="1200" placeholder="For example: It has not moved for several days and appears inoperable.">${escapeHtml(d.description || '')}</textarea><span class="hint">Do not include personal information about other people.</span></div></div><div id="vehicle-error"></div><div class="row" style="margin-top:22px"><button class="btn secondary" type="button" id="back">Back</button><button class="btn" type="submit">Continue</button></div></form>`;
  if (step === 3) content = `<h1>Where is the vehicle?</h1><p class="lead">Enter the nearest address, intersection, or clear location description. Your coordinates help staff locate it and are not shown publicly.</p><form id="location-form" novalidate><div class="form-grid"><div class="field full"><label for="address">Vehicle location <span class="required">required</span></label><input id="address" maxlength="320" value="${escapeHtml(d.address || '')}" placeholder="Street address, intersection, or landmark"><span class="hint">Example: Kamehameha Ave near Wailoa River, Hilo</span></div><div class="field"><label for="latitude">Latitude <span class="hint">optional</span></label><input id="latitude" inputmode="decimal" value="${escapeHtml(d.latitude ?? '')}" placeholder="19.72"></div><div class="field"><label for="longitude">Longitude <span class="hint">optional</span></label><input id="longitude" inputmode="decimal" value="${escapeHtml(d.longitude ?? '')}" placeholder="-155.08"></div><div class="field full"><div class="location-controls"><button class="btn secondary" id="use-location" type="button">Use my current location</button><span id="location-message" class="hint">You can also enter a location manually.</span></div></div><div class="field full"><label for="observedAt">When did you observe it? <span class="hint">optional</span></label><input id="observedAt" type="datetime-local" value="${escapeHtml(d.observedAt || '')}"></div></div><div id="location-error"></div><div class="row" style="margin-top:22px"><button class="btn secondary" type="button" id="back">Back</button><button class="btn" type="submit">Review report</button></div></form>`;
  if (step === 4) content = `<h1>Review your report</h1><p class="lead">Confirm the information below before submitting. Staff will review the report.</p><div class="review"><div class="review-block">${d.photoData ? `<img class="upload-preview" src="${d.photoData}" alt="Vehicle photo preview">` : ''}</div><dl class="review-block"><dt>Vehicle</dt><dd>${escapeHtml([d.color, d.make, d.model, d.vehicleType].filter(Boolean).join(' ') || 'See description')}</dd><dt>License plate</dt><dd>${escapeHtml([d.plate, d.plateState].filter(Boolean).join(' · ') || 'Not provided')}</dd><dt>Description</dt><dd>${escapeHtml(d.description || 'Not provided')}</dd></dl><dl class="review-block"><dt>Location</dt><dd>${escapeHtml(d.address)}</dd><dt>Observed</dt><dd>${d.observedAt ? fmtTime(d.observedAt) : 'Not provided'}</dd></dl><div class="notice">Submitting creates a public report record. County staff review reports; a submission does not promise immediate removal.</div><div id="submit-error"></div><div class="row"><button class="btn secondary" id="back" type="button">Back</button><button class="btn" id="submit-report" type="button">Submit report</button></div></div>`;
  publicPage('report', `<section class="report-shell"><div class="breadcrumbs"><a href="/" data-route>Home</a> / Report vehicle</div>${progress}<article class="card form-card">${content}</article></section>`);
  bindReport(step);
}
function bindReport(step) {
  const back = document.getElementById('back'); if (back) back.addEventListener('click', () => reportPage(step - 1));
  if (step === 1) {
    document.getElementById('photo-input').addEventListener('change', async event => {
      const file = event.target.files[0]; if (!file) return;
      const error = document.getElementById('photo-error'); error.innerHTML = '';
      if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) { error.innerHTML = '<p class="field-error">Choose a JPG, PNG, or WebP image.</p>'; return; }
      if (file.size > 12 * 1024 * 1024) { error.innerHTML = '<p class="field-error">Choose an image smaller than 12 MB.</p>'; return; }
      try { state.draft.photoData = await resizeImage(file); reportPage(1); } catch { error.innerHTML = '<p class="field-error">We could not read that image. Try another photo.</p>'; }
    });
    document.getElementById('photo-next').addEventListener('click', () => { if (!state.draft.photoData) { document.getElementById('photo-error').innerHTML = '<p class="field-error">Add a clear vehicle photo to continue.</p>'; return; } reportPage(2); });
    const remove = document.getElementById('remove-photo'); if (remove) remove.addEventListener('click', () => { delete state.draft.photoData; reportPage(1); });
  }
  if (step === 2) document.getElementById('vehicle-form').addEventListener('submit', event => { event.preventDefault(); const g = id => document.getElementById(id).value.trim(); Object.assign(state.draft, { plate: g('plate'), plateState: g('plateState'), make: g('make'), model: g('model'), color: g('color'), vehicleType: g('vehicleType'), description: g('description') }); if (!state.draft.plate && !state.draft.make && !state.draft.model && !state.draft.description) { document.getElementById('vehicle-error').innerHTML = '<p class="field-error">Add vehicle details or a short description.</p>'; return; } reportPage(3); });
  if (step === 3) {
    document.getElementById('use-location').addEventListener('click', () => { const msg = document.getElementById('location-message'); if (!navigator.geolocation) { msg.textContent = 'Location is unavailable in this browser. Enter it manually.'; return; } msg.textContent = 'Getting your location…'; navigator.geolocation.getCurrentPosition(p => { document.getElementById('latitude').value = p.coords.latitude.toFixed(6); document.getElementById('longitude').value = p.coords.longitude.toFixed(6); msg.textContent = 'Current coordinates added. Please still enter the nearest address.'; }, () => { msg.textContent = 'Location permission was unavailable. Enter it manually.'; }, { enableHighAccuracy: true, timeout: 10000 }); });
    document.getElementById('location-form').addEventListener('submit', event => { event.preventDefault(); const address = document.getElementById('address').value.trim(); const latitude = document.getElementById('latitude').value.trim(); const longitude = document.getElementById('longitude').value.trim(); if (address.length < 5) { document.getElementById('location-error').innerHTML = '<p class="field-error">Enter the vehicle location or nearest address.</p>'; return; } if ((latitude && !longitude) || (!latitude && longitude)) { document.getElementById('location-error').innerHTML = '<p class="field-error">Enter both coordinates or leave both blank.</p>'; return; } Object.assign(state.draft, { address, latitude, longitude, observedAt: document.getElementById('observedAt').value }); reportPage(4); });
  }
  if (step === 4) document.getElementById('submit-report').addEventListener('click', async () => { const btn = document.getElementById('submit-report'); btn.disabled = true; btn.textContent = 'Submitting…'; try { const result = await api('/api/public/reports', { method: 'POST', body: JSON.stringify({ ...state.draft, startedAt: state.startedAt, website: '' }) }); state.confirmation = result; state.draft = {}; state.startedAt = Date.now(); navigate('/report/confirmation'); } catch (error) { document.getElementById('submit-error').innerHTML = friendlyError(error); btn.disabled = false; btn.textContent = 'Submit report'; } });
}
function resizeImage(file) { return new Promise((resolve, reject) => { const reader = new FileReader(); reader.onerror = reject; reader.onload = () => { const image = new Image(); image.onerror = reject; image.onload = () => { const max = 1600; const ratio = Math.min(1, max / Math.max(image.width, image.height)); const canvas = document.createElement('canvas'); canvas.width = Math.max(1, Math.round(image.width * ratio)); canvas.height = Math.max(1, Math.round(image.height * ratio)); canvas.getContext('2d').drawImage(image, 0, 0, canvas.width, canvas.height); resolve(canvas.toDataURL('image/jpeg', .84)); }; image.src = reader.result; }; reader.readAsDataURL(file); }); }
function confirmationPage() {
  const item = state.confirmation;
  if (!item) return navigate('/report', true);
  publicPage('report', `<section class="report-shell"><article class="card form-card"><div class="eyebrow">Report received</div><h1>Thank you for helping your community.</h1><p class="lead">Your report has been submitted for county staff to review. Please save this Report ID.</p><div class="confirm-id" aria-label="Report ID ${escapeHtml(item.reportId)}">${escapeHtml(item.reportId)}</div><p class="notice success">Current public status: <strong>${escapeHtml(item.status)}</strong>. ${escapeHtml(item.message)}</p><div class="row"><a class="btn" href="/status?id=${encodeURIComponent(item.reportId)}" data-route>Check this report status</a><a class="btn secondary" href="/" data-route>Return home</a></div></article></section>`);
}
function statusPage() {
  const initial = new URLSearchParams(location.search).get('id') || '';
  publicPage('status', `<section class="report-shell"><div class="page-title"><div class="eyebrow">Public report lookup</div><h1>Check report status</h1><p class="lead">Enter the Report ID from your confirmation. Public status never includes staff notes or exact location information.</p></div><article class="card form-card"><form id="status-form"><div class="field"><label for="report-id">Report ID</label><input id="report-id" value="${escapeHtml(initial)}" placeholder="AV-2026-123456" autocomplete="off"><span class="hint">Example: AV-2026-123456</span></div><div class="row" style="margin-top:17px"><button class="btn" type="submit">Check status</button></div></form><div id="status-result" style="margin-top:18px"></div></article></section>`);
  document.getElementById('status-form').addEventListener('submit', async e => { e.preventDefault(); const id = document.getElementById('report-id').value.trim().toUpperCase(); const result = document.getElementById('status-result'); if (!id) { result.innerHTML = '<p class="field-error">Enter a Report ID.</p>'; return; } result.innerHTML = '<p class="subtle">Looking up your report…</p>'; try { const data = await api(`/api/public/status?id=${encodeURIComponent(id)}`); result.innerHTML = `<div class="review-block"><div class="card-header"><div><div class="eyebrow">${escapeHtml(data.reportId)}</div><h2 style="font-size:1.5rem;margin:4px 0">Report status</h2></div>${statusBadge(data.status)}</div><dl class="detail-list"><div><dt>Submitted</dt><dd>${fmtTime(data.submittedAt)}</dd></div><div><dt>Observed</dt><dd>${fmtDate(data.observedAt)}</dd></div></dl><p class="subtle" style="margin:15px 0 0">${escapeHtml(data.publicMessage)}</p></div>`; } catch (error) { result.innerHTML = friendlyError(error); } });
  if (initial) document.getElementById('status-form').dispatchEvent(new Event('submit'));
}

async function ensureStaff() {
  if (state.user && state.csrf) return true;
  try { const data = await api('/api/auth/me'); state.user = data.user; state.csrf = data.csrfToken; return true; } catch { state.user = null; state.csrf = null; return false; }
}
function staffShell(active, content) {
  const nav = [['dashboard','Dashboard','◫'],['reports','Reports','▤'],['cases','Vehicle cases','▣'],['map','Map','⌖'],['review','Review queue','✓'],['statistics','Statistics','▥'],['settings','Settings','⚙']];
  app.innerHTML = `<div class="staff-shell"><header class="staff-top"><button class="staff-menu" aria-label="Toggle staff navigation">☰</button><a class="brand" href="/staff/dashboard" data-route><span class="brand-mark">VW</span><span><small>Authorized staff</small>VehicleWatch</span></a><div class="user-chip"><span>${escapeHtml(state.user.name)} · ${escapeHtml(state.user.role)}</span><button class="btn secondary small" id="logout" type="button">Sign out</button></div></header><div class="staff-layout"><aside class="sidebar"><nav aria-label="Staff navigation">${nav.map(([id, label, icon]) => `<a href="/staff/${id}" data-route class="${active === id ? 'active' : ''}"><span aria-hidden="true">${icon}</span>${label}</a>`).join('')}</nav></aside><main class="staff-main">${content}</main></div></div>`;
  bindCommon(); document.querySelector('.staff-menu')?.addEventListener('click', () => document.querySelector('.sidebar').classList.toggle('open')); document.getElementById('logout').addEventListener('click', logout);
}
async function logout() { try { await api('/api/auth/logout', { method: 'POST', body: '{}' }); } catch {} state.user = null; state.csrf = null; navigate('/staff/login'); }
async function staffLoginPage() {
  if (await ensureStaff()) return navigate('/staff/dashboard', true);
  app.innerHTML = `<main class="login-page"><section class="login-box"><a class="brand" style="color:var(--brand-dark)" href="/" data-route><span class="brand-mark" style="background:var(--brand);color:#fff">VW</span><span><small style="color:var(--muted)">Authorized staff</small>VehicleWatch</span></a><h1 style="font-size:2.1rem;margin-top:25px">Staff sign in</h1><p class="subtle">This area is for authorized county staff. Public reporting does not require an account.</p><form id="login-form"><div class="stack"><div class="field"><label for="email">Work email</label><input id="email" type="email" autocomplete="username" required></div><div class="field"><label for="password">Password</label><input id="password" type="password" autocomplete="current-password" required></div><div id="login-error"></div><button class="btn wide" type="submit">Sign in securely</button></div></form><p class="demo-credentials"><strong>Local demo only:</strong><br>admin@vehiclewatch.local<br>ChangeMe!2026</p><p><a href="/" data-route>← Return to public site</a></p></section></main>`;
  bindCommon(); document.getElementById('login-form').addEventListener('submit', async e => { e.preventDefault(); const btn = e.target.querySelector('button'); btn.disabled = true; try { const result = await api('/api/auth/login', { method: 'POST', body: JSON.stringify({ email: document.getElementById('email').value, password: document.getElementById('password').value }) }); state.user = result.user; state.csrf = result.csrfToken; navigate('/staff/dashboard'); } catch (error) { document.getElementById('login-error').innerHTML = friendlyError(error); btn.disabled = false; } });
}
function renderLoading(active, title = 'Loading…') { staffShell(active, `<h1>${title}</h1><p class="subtle">Loading current information…</p>`); }
function mapPlot(items) { const geocoded = items.filter(i => Number.isFinite(i.latitude) && Number.isFinite(i.longitude)); if (!geocoded.length) return '<div class="empty">No active cases with coordinates are available for the map.</div>'; const minLat = Math.min(...geocoded.map(i => i.latitude)), maxLat = Math.max(...geocoded.map(i => i.latitude)), minLng = Math.min(...geocoded.map(i => i.longitude)), maxLng = Math.max(...geocoded.map(i => i.longitude)); const spanLat = Math.max(.02, maxLat - minLat), spanLng = Math.max(.02, maxLng - minLng); return `<div class="map-plot" role="region" aria-label="Active vehicle case map">${geocoded.map((i, n) => { const x = 10 + 80 * ((i.longitude - minLng) / spanLng); const y = 88 - 74 * ((i.latitude - minLat) / spanLat); return `<button class="marker ${statusClass(i.status).replace('status-', '')}" style="left:${x}%;top:${y}%" title="${escapeHtml(i.case_id || i.caseId)}: ${escapeHtml(i.address || 'Location') }" data-case="${i.id || ''}">${n + 1}</button>`; }).join('')}</div><p class="map-legend">Markers are shown using report coordinates. Use the location link in a case to open it in OpenStreetMap.</p>`; }
async function dashboardPage() {
  if (!await ensureStaff()) return navigate('/staff/login', true); renderLoading('dashboard', 'Dashboard');
  try { const data = await api('/api/staff/dashboard'); staffShell('dashboard', `<div class="card-header"><div><div class="eyebrow">Staff overview</div><h1>Dashboard</h1></div><a class="btn" href="/staff/review" data-route>Open review queue</a></div><section class="summary-grid"><div class="metric"><span>New reports</span><strong>${data.counts.newReports}</strong></div><div class="metric"><span>Needs review</span><strong>${data.counts.reviewQueue}</strong></div><div class="metric"><span>Possible duplicates</span><strong>${data.counts.possibleDuplicates}</strong></div><div class="metric"><span>Active cases</span><strong>${data.counts.activeCases}</strong></div><div class="metric"><span>Resolved this month</span><strong>${data.counts.resolvedThisMonth}</strong></div></section><section class="staff-grid"><article class="card"><div class="card-header"><h2>Recent reports</h2><a href="/staff/reports" data-route>All reports</a></div>${reportsTable(data.recent)}</article><aside class="card"><div class="card-header"><h2>Active map</h2><a href="/staff/map" data-route>Open map</a></div>${mapPlot(data.mapCases)}</aside></section>`); bindCaseMarkers(); } catch (error) { staffShell('dashboard', `<h1>Dashboard</h1>${friendlyError(error)}`); }
}
function reportsTable(rows) { if (!rows.length) return '<div class="empty">No reports found.</div>'; return `<div class="table-wrap"><table><thead><tr><th>Report</th><th>Vehicle</th><th class="hide-mobile">Location</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(r => `<tr><td><strong>${escapeHtml(r.reportId)}</strong><br><span class="hint">${fmtDate(r.submittedAt)}</span></td><td>${escapeHtml(vehicleName(r))}<br><span class="hint">${escapeHtml(r.plate || 'No plate')}</span></td><td class="hide-mobile">${escapeHtml(r.address)}</td><td>${statusBadge(r.status)}</td><td><button class="table-link" data-open-report="${r.id}">Review</button></td></tr>`).join('')}</tbody></table></div>`; }
function bindReportTable() { document.querySelectorAll('[data-open-report]').forEach(btn => btn.addEventListener('click', () => navigate(`/staff/report/${btn.dataset.openReport}`))); }
function bindCaseMarkers() { bindReportTable(); document.querySelectorAll('[data-case]').forEach(btn => btn.addEventListener('click', () => { if (btn.dataset.case) navigate(`/staff/case/${btn.dataset.case}`); })); }
async function reportsPage(reviewOnly = false) {
  if (!await ensureStaff()) return navigate('/staff/login', true); renderLoading(reviewOnly ? 'review' : 'reports', reviewOnly ? 'Review queue' : 'Reports');
  const params = new URLSearchParams(location.search); const initialStatus = reviewOnly ? (params.get('status') || 'New') : (params.get('status') || ''); const initialQuery = params.get('q') || '';
  try { const data = await api(`/api/staff/reports?q=${encodeURIComponent(initialQuery)}&status=${encodeURIComponent(initialStatus)}`); const active = reviewOnly ? 'review' : 'reports'; staffShell(active, `<div class="card-header"><div><div class="eyebrow">${reviewOnly ? 'Actionable reports' : 'Report records'}</div><h1>${reviewOnly ? 'Review queue' : 'Reports'}</h1></div><span class="subtle">${data.total} result${data.total === 1 ? '' : 's'}</span></div><article class="card"><form class="filters" id="report-filters"><div class="field"><label for="report-q">Search</label><input id="report-q" value="${escapeHtml(initialQuery)}" placeholder="Report ID, plate, vehicle, location"></div><div class="field compact"><label for="report-status">Status</label><select id="report-status"><option value="">All statuses</option>${['New','Under Review','Verified','Needs more information','Duplicate','Rejected','Archived'].map(s => `<option ${initialStatus === s ? 'selected' : ''}>${s}</option>`).join('')}</select></div><button class="btn" type="submit">Apply filters</button></form>${reportsTable(data.rows)}${data.pages > 1 ? `<p class="subtle">Page ${data.page} of ${data.pages}. Refine your search to narrow results.</p>` : ''}</article>`); bindReportTable(); document.getElementById('report-filters').addEventListener('submit', e => { e.preventDefault(); const q = document.getElementById('report-q').value.trim(); const status = document.getElementById('report-status').value; navigate(`/staff/${reviewOnly ? 'review' : 'reports'}?q=${encodeURIComponent(q)}&status=${encodeURIComponent(status)}`); }); } catch (error) { staffShell(reviewOnly ? 'review' : 'reports', `<h1>Reports</h1>${friendlyError(error)}`); }
}
async function reportDetailPage(id) {
  if (!await ensureStaff()) return navigate('/staff/login', true); renderLoading('reports', 'Report review');
  try { const data = await api(`/api/staff/reports/${id}`); const r = data.report; const canManage = ['Case Manager', 'Administrator'].includes(state.user.role); staffShell('reports', `<div class="breadcrumbs"><a href="/staff/reports" data-route>Reports</a> / ${escapeHtml(r.reportId)}</div><div class="card-header"><div><div class="eyebrow">Report record</div><h1>${escapeHtml(r.reportId)}</h1></div>${statusBadge(r.status)}</div><section class="case-detail"><article class="card"><div class="photo-box">${r.photoUrl ? `<img src="${r.photoUrl}" alt="Uploaded vehicle photo">` : '<span class="subtle">No photo available</span>'}</div><p class="subtle" style="margin:12px 0 0">Private photo — authorized staff only</p></article><article class="card"><h2>Vehicle and location</h2><dl class="detail-list"><div><dt>Vehicle</dt><dd>${escapeHtml(vehicleName(r))}</dd></div><div><dt>Plate</dt><dd>${escapeHtml([r.plate, r.plateState].filter(Boolean).join(' · ') || 'Not provided')}</dd></div><div><dt>Location</dt><dd>${escapeHtml(r.address)}</dd></div><div><dt>Submitted</dt><dd>${fmtTime(r.submittedAt)}</dd></div><div><dt>Observed</dt><dd>${fmtTime(r.observedAt)}</dd></div><div><dt>Linked case</dt><dd>${r.caseId ? escapeHtml(r.caseId) : 'None'}</dd></div></dl><h3 style="margin-top:18px">Public description</h3><p>${escapeHtml(r.description || 'No description provided.')}</p>${Number.isFinite(r.latitude) ? `<a target="_blank" rel="noreferrer" href="https://www.openstreetmap.org/?mlat=${encodeURIComponent(r.latitude)}&mlon=${encodeURIComponent(r.longitude)}#map=17/${encodeURIComponent(r.latitude)}/${encodeURIComponent(r.longitude)}">Open staff location in OpenStreetMap ↗</a>` : ''}</article></section><section class="staff-grid" style="margin-top:20px"><article class="card"><h2>Review decision</h2><form id="report-status-form" class="stack"><div class="field"><label for="new-status">Report status</label><select id="new-status">${['New','Under Review','Verified','Needs more information','Duplicate','Rejected','Archived'].map(s => `<option ${r.status === s ? 'selected' : ''}>${s}</option>`).join('')}</select></div><div class="field"><label for="status-note">Reason or review note <span class="hint">optional</span></label><textarea id="status-note" maxlength="1200" placeholder="Record the basis for this staff decision."></textarea></div><button class="btn" type="submit">Save review decision</button></form><hr><h2>Staff notes</h2><form id="note-form" class="stack"><div class="field"><label for="new-note">Internal note</label><textarea id="new-note" maxlength="1600" placeholder="Visible only to authorized staff."></textarea></div><button class="btn secondary" type="submit">Add staff note</button></form><div>${data.notes.map(n => `<div class="note"><strong>${escapeHtml(n.name)}</strong> <span class="hint">${fmtTime(n.created_at)}</span><br>${escapeHtml(n.note)}</div>`).join('') || '<p class="subtle">No staff notes yet.</p>'}</div></article><aside class="card"><h2>Vehicle case</h2>${r.caseId ? `<p>This report is linked to <strong>${escapeHtml(r.caseId)}</strong>.</p>` : `<p class="subtle">Link this report to an existing case or create a new case after review.</p>`}${canManage ? `<form id="case-form" class="stack"><div class="field"><label for="existing-case">Existing Case ID <span class="hint">optional</span></label><input id="existing-case" placeholder="CASE-2026-1234"></div><div class="field"><label for="case-note">Link note <span class="hint">optional</span></label><textarea id="case-note" maxlength="600" placeholder="Why this report belongs to this case."></textarea></div><button class="btn" type="submit">${r.caseId ? 'Move / link case' : 'Create or link case'}</button></form>` : '<p class="notice warning">Your reviewer role can assess reports but cannot create or link vehicle cases.</p>'}<hr><h2>Possible matches</h2>${data.duplicates.length ? data.duplicates.map(d => `<div class="duplicate"><strong>${escapeHtml(d.publicId)}</strong> · ${d.score}% match<br><span class="hint">${escapeHtml(d.reasons.join(', '))}</span><div class="row" style="margin-top:8px"><button class="btn secondary small" data-duplicate="not-match" data-target="${escapeHtml(d.kind === 'case' ? d.publicId : (d.caseId || ''))}">Not a match</button><button class="btn secondary small" data-duplicate="later" data-target="${escapeHtml(d.kind === 'case' ? d.publicId : (d.caseId || ''))}">Review later</button>${canManage && (d.kind === 'case' || d.caseId) ? `<button class="btn small" data-duplicate="link" data-target="${escapeHtml(d.kind === 'case' ? d.publicId : d.caseId)}">Confirm & link</button>` : ''}</div></div>`).join('') : '<p class="subtle">No likely matches were found. Suggestions are advisory and never merge records automatically.</p>'}</aside></section><section class="card" style="margin-top:20px"><h2>Audit and review history</h2><div class="timeline">${data.history.map(h => `<div class="timeline-item"><strong>${escapeHtml(h.action)}</strong>${h.previous_status || h.new_status ? `<br><span class="hint">${escapeHtml(h.previous_status || '—')} → ${escapeHtml(h.new_status || '—')}</span>` : ''}${h.notes ? `<br>${escapeHtml(h.notes)}` : ''}<br><time>${fmtTime(h.created_at)}${h.name ? ` · ${escapeHtml(h.name)}` : ''}</time></div>`).join('') || '<p class="subtle">No review history yet.</p>'}</div></section>`); bindReportDetail(id); } catch (error) { staffShell('reports', `<h1>Report review</h1>${friendlyError(error)}`); }
}
function bindReportDetail(id) {
  document.getElementById('report-status-form').addEventListener('submit', async e => { e.preventDefault(); try { await api(`/api/staff/reports/${id}`, { method: 'PATCH', body: JSON.stringify({ status: document.getElementById('new-status').value, note: document.getElementById('status-note').value }) }); toast('Review decision saved.'); reportDetailPage(id); } catch (error) { toast(error.message); } });
  document.getElementById('note-form').addEventListener('submit', async e => { e.preventDefault(); try { await api(`/api/staff/reports/${id}/note`, { method: 'POST', body: JSON.stringify({ note: document.getElementById('new-note').value }) }); toast('Staff note added.'); reportDetailPage(id); } catch (error) { toast(error.message); } });
  document.getElementById('case-form')?.addEventListener('submit', async e => { e.preventDefault(); try { const out = await api(`/api/staff/reports/${id}/case`, { method: 'POST', body: JSON.stringify({ existingCaseId: document.getElementById('existing-case').value, note: document.getElementById('case-note').value }) }); toast(`Linked to ${out.caseId}.`); reportDetailPage(id); } catch (error) { toast(error.message); } });
  document.querySelectorAll('[data-duplicate]').forEach(btn => btn.addEventListener('click', async () => { try { await api(`/api/staff/reports/${id}/duplicate`, { method: 'POST', body: JSON.stringify({ action: btn.dataset.duplicate, targetCaseId: btn.dataset.target }) }); toast('Duplicate review saved.'); reportDetailPage(id); } catch (error) { toast(error.message); } }));
}
async function casesPage() {
  if (!await ensureStaff()) return navigate('/staff/login', true); renderLoading('cases', 'Vehicle cases'); const params = new URLSearchParams(location.search); const q = params.get('q') || '', status = params.get('status') || '';
  try { const data = await api(`/api/staff/cases?q=${encodeURIComponent(q)}&status=${encodeURIComponent(status)}`); staffShell('cases', `<div class="card-header"><div><div class="eyebrow">Investigation records</div><h1>Vehicle cases</h1></div><span class="subtle">${data.rows.length} case${data.rows.length === 1 ? '' : 's'}</span></div><article class="card"><form class="filters" id="case-filters"><div class="field"><label for="case-q">Search</label><input id="case-q" value="${escapeHtml(q)}" placeholder="Case ID, plate, vehicle, location"></div><div class="field compact"><label for="case-status">Status</label><select id="case-status"><option value="">All statuses</option>${['New','Under Review','Verified','Action in Progress','Resolved','Archived'].map(s => `<option ${status === s ? 'selected' : ''}>${s}</option>`).join('')}</select></div><button class="btn" type="submit">Apply filters</button></form><div class="table-wrap"><table><thead><tr><th>Case</th><th>Vehicle</th><th class="hide-mobile">Location</th><th>Reports</th><th>Status</th><th></th></tr></thead><tbody>${data.rows.map(c => `<tr><td><strong>${escapeHtml(c.case_id)}</strong><br><span class="hint">${fmtDate(c.created_at)}</span></td><td>${escapeHtml(vehicleName(c))}<br><span class="hint">${escapeHtml(c.plate || 'No plate')}</span></td><td class="hide-mobile">${escapeHtml(c.address || 'Not provided')}</td><td>${c.report_count}</td><td>${statusBadge(c.status)}</td><td><button class="table-link" data-open-case="${c.id}">Open</button></td></tr>`).join('') || '<tr><td colspan="6" class="empty">No vehicle cases found.</td></tr>'}</tbody></table></div></article>`); document.querySelectorAll('[data-open-case]').forEach(b => b.addEventListener('click', () => navigate(`/staff/case/${b.dataset.openCase}`))); document.getElementById('case-filters').addEventListener('submit', e => { e.preventDefault(); navigate(`/staff/cases?q=${encodeURIComponent(document.getElementById('case-q').value.trim())}&status=${encodeURIComponent(document.getElementById('case-status').value)}`); }); } catch (error) { staffShell('cases', `<h1>Vehicle cases</h1>${friendlyError(error)}`); }
}
async function caseDetailPage(id) {
  if (!await ensureStaff()) return navigate('/staff/login', true); renderLoading('cases', 'Vehicle case');
  try { const data = await api(`/api/staff/cases/${id}`); const c = data.item; const canManage = ['Case Manager','Administrator'].includes(state.user.role); staffShell('cases', `<div class="breadcrumbs"><a href="/staff/cases" data-route>Vehicle cases</a> / ${escapeHtml(c.case_id)}</div><div class="card-header"><div><div class="eyebrow">Vehicle case</div><h1>${escapeHtml(c.case_id)}</h1></div>${statusBadge(c.status)}</div><section class="staff-grid"><article class="card"><h2>Case details</h2><dl class="detail-list"><div><dt>Vehicle</dt><dd>${escapeHtml(vehicleName(c))}</dd></div><div><dt>Plate</dt><dd>${escapeHtml([c.plate,c.plate_state].filter(Boolean).join(' · ') || 'Not provided')}</dd></div><div><dt>Location</dt><dd>${escapeHtml(c.address || 'Not provided')}</dd></div><div><dt>Created</dt><dd>${fmtTime(c.created_at)}</dd></div></dl>${Number.isFinite(c.latitude) ? `<p><a target="_blank" rel="noreferrer" href="https://www.openstreetmap.org/?mlat=${encodeURIComponent(c.latitude)}&mlon=${encodeURIComponent(c.longitude)}#map=17/${encodeURIComponent(c.latitude)}/${encodeURIComponent(c.longitude)}">Open location in OpenStreetMap ↗</a></p>` : ''}<hr><h2>Case status</h2>${canManage ? `<form id="case-status-form" class="stack"><div class="field"><label for="new-case-status">Status</label><select id="new-case-status">${['New','Under Review','Verified','Action in Progress','Resolved','Archived'].map(s => `<option ${c.status === s ? 'selected' : ''}>${s}</option>`).join('')}</select></div><div class="field"><label for="case-resolution">Status note / resolution</label><textarea id="case-resolution" maxlength="1400" placeholder="Record action taken or resolution details.">${escapeHtml(c.resolution_note || '')}</textarea></div><button class="btn" type="submit">Save case status</button></form>` : '<p class="notice warning">Your reviewer role cannot update vehicle case status.</p>'}</article><aside class="card"><h2>Linked reports</h2>${data.reports.length ? data.reports.map(r => `<div class="duplicate"><strong>${escapeHtml(r.reportId)}</strong> ${statusBadge(r.status)}<br><span class="hint">${escapeHtml(vehicleName(r))} · ${fmtDate(r.submittedAt)}</span><br><button class="table-link" data-open-report="${r.id}" style="margin-top:6px">Open report</button></div>`).join('') : '<p class="subtle">No reports are linked to this case.</p>'}<h2 style="margin-top:22px">Case history</h2><div class="timeline">${data.history.map(h => `<div class="timeline-item"><strong>${escapeHtml(h.action)}</strong><br><span class="hint">${escapeHtml(h.previous_status || '—')} → ${escapeHtml(h.new_status || '—')}</span>${h.notes ? `<br>${escapeHtml(h.notes)}` : ''}<br><time>${fmtTime(h.created_at)}${h.name ? ` · ${escapeHtml(h.name)}` : ''}</time></div>`).join('') || '<p class="subtle">No case history yet.</p>'}</div></aside></section>`); bindReportTable(); document.getElementById('case-status-form')?.addEventListener('submit', async e => { e.preventDefault(); try { await api(`/api/staff/cases/${id}`, { method: 'PATCH', body: JSON.stringify({ status: document.getElementById('new-case-status').value, note: document.getElementById('case-resolution').value }) }); toast('Case status saved.'); caseDetailPage(id); } catch (error) { toast(error.message); } }); } catch (error) { staffShell('cases', `<h1>Vehicle case</h1>${friendlyError(error)}`); }
}
async function mapPage() {
  if (!await ensureStaff()) return navigate('/staff/login', true); renderLoading('map', 'Active vehicle map'); const current = new URLSearchParams(location.search).get('status') || '';
  try { const data = await api(`/api/staff/map?status=${encodeURIComponent(current)}`); staffShell('map', `<div class="card-header"><div><div class="eyebrow">Authorized staff only</div><h1>Active vehicle map</h1></div><span class="subtle">Resolved and archived cases are hidden by default.</span></div><article class="card"><form id="map-filter" class="filters"><div class="field compact"><label for="map-status">Case status</label><select id="map-status"><option value="">All active statuses</option>${['New','Under Review','Verified','Action in Progress','Resolved','Archived'].map(s => `<option ${current === s ? 'selected' : ''}>${s}</option>`).join('')}</select></div><button class="btn" type="submit">Filter map</button></form>${mapPlot(data.rows)}<div class="table-wrap" style="margin-top:18px"><table><thead><tr><th>Case</th><th>Location</th><th>Status</th><th></th></tr></thead><tbody>${data.rows.map(c => `<tr><td>${escapeHtml(c.case_id)}</td><td>${escapeHtml(c.address || 'No coordinates')}</td><td>${statusBadge(c.status)}</td><td><button class="table-link" data-open-case="${c.id}">Open case</button></td></tr>`).join('') || '<tr><td colspan="4" class="empty">No matching active cases.</td></tr>'}</tbody></table></div></article>`); document.getElementById('map-filter').addEventListener('submit', e => { e.preventDefault(); navigate(`/staff/map?status=${encodeURIComponent(document.getElementById('map-status').value)}`); }); document.querySelectorAll('[data-open-case]').forEach(b => b.addEventListener('click', () => navigate(`/staff/case/${b.dataset.openCase}`))); bindCaseMarkers(); } catch (error) { staffShell('map', `<h1>Active vehicle map</h1>${friendlyError(error)}`); }
}
async function statisticsPage() {
  if (!await ensureStaff()) return navigate('/staff/login', true); renderLoading('statistics', 'Statistics');
  try { const data = await api('/api/staff/stats'); const maxReport = Math.max(1, ...data.byReport.map(i => i.count)); const maxCase = Math.max(1, ...data.byCase.map(i => i.count)); staffShell('statistics', `<div class="eyebrow">Operational snapshot</div><h1>Statistics</h1><section class="staff-grid"><article class="card"><h2>Reports by status</h2>${data.byReport.map(i => `<div class="chart-row"><span class="bar-label">${escapeHtml(i.status)}</span><div class="bar" style="width:${Math.max(3, i.count / maxReport * 62)}%"></div><strong>${i.count}</strong></div>`).join('') || '<p class="subtle">No report data.</p>'}</article><article class="card"><h2>Vehicle cases by status</h2>${data.byCase.map(i => `<div class="chart-row"><span class="bar-label">${escapeHtml(i.status)}</span><div class="bar" style="width:${Math.max(3, i.count / maxCase * 62)}%"></div><strong>${i.count}</strong></div>`).join('') || '<p class="subtle">No vehicle case data.</p>'}</article></section><section class="card" style="margin-top:18px"><h2>Submission volume</h2>${data.monthly.map(i => `<div class="chart-row"><span class="bar-label">${escapeHtml(i.month)}</span><div class="bar" style="width:${Math.max(3, i.count * 18)}px"></div><strong>${i.count}</strong></div>`).join('') || '<p class="subtle">No historical data yet.</p>'}<p class="hint">Statistics are based on real application records and are intended for operational awareness, not automated enforcement decisions.</p></section>`); } catch (error) { staffShell('statistics', `<h1>Statistics</h1>${friendlyError(error)}`); }
}
async function settingsPage() {
  if (!await ensureStaff()) return navigate('/staff/login', true); staffShell('settings', `<div class="eyebrow">Administration</div><h1>Settings</h1><section class="content-grid"><article class="card prose"><h2>Deployment configuration</h2><p>This MVP stores local development data in SQLite and private files in the application storage directory. Production deployments should use a managed database, encrypted private object storage, HTTPS, automated backups, and the county’s approved identity provider.</p><p><strong>Active role:</strong> ${escapeHtml(state.user.role)}. Server-side authorization is enforced for all staff APIs.</p><h3>Future AI integration</h3><p>Duplicate matching is advisory. The server’s duplicate-analysis boundary can be extended with approved image similarity or vehicle analysis, but it must never automatically merge cases, reject reports, or resolve cases.</p></article><aside class="card"><h2>Security controls</h2><ul><li>HTTP-only, expiring staff sessions</li><li>Role checks on every staff request</li><li>CSRF verification on staff changes</li><li>Server-side file signature and image dimension validation</li><li>Private photo URLs</li><li>Source rate limiting and honeypot/timing checks</li><li>Append-only audit events</li></ul><p class="notice warning">This local demo includes a documented seed account. Change or remove it before a deployment.</p></aside></section>`);
}

async function render() {
  const path = location.pathname.replace(/\/$/, '') || '/';
  if (path === '/') return home();
  if (path === '/report') return reportPage(1);
  if (path === '/report/confirmation') return confirmationPage();
  if (path === '/status') return statusPage();
  if (['/about','/faq','/county','/contact'].includes(path)) return infoPage(path.slice(1));
  if (path === '/staff/login') return staffLoginPage();
  if (path === '/staff/dashboard' || path === '/staff') return dashboardPage();
  if (path === '/staff/reports') return reportsPage(false);
  if (path === '/staff/review') return reportsPage(true);
  if (path === '/staff/cases') return casesPage();
  if (path === '/staff/map') return mapPage();
  if (path === '/staff/statistics') return statisticsPage();
  if (path === '/staff/settings') return settingsPage();
  const reportMatch = path.match(/^\/staff\/report\/(\d+)$/); if (reportMatch) return reportDetailPage(reportMatch[1]);
  const caseMatch = path.match(/^\/staff\/case\/(\d+)$/); if (caseMatch) return caseDetailPage(caseMatch[1]);
  return home();
}
render();
